import DetailPresenter from '../../presenters/detail-presenter';

class DetailPage {
  constructor() {
    this.presenter = new DetailPresenter(this);
  }

  async render(id) {
    return `
      <section class="detail-page" aria-label="Detail Cerita">
        <div id="detailContent"></div>
        <div id="mapDetail" style="height:200px;"></div>
      </section>
    `;
  }

  async afterRender(id) {
    await this.presenter.showDetail(id);
  }

  showDetail(story) {
    const el = document.getElementById('detailContent');
    el.innerHTML = `
      <h2>${story.name}</h2>
      <img src="${story.photoUrl}" alt="Foto cerita oleh ${story.name}" />
      <p>${story.description}</p>
      <p><strong>Lokasi:</strong> ${story.lat && story.lon ? `${story.lat}, ${story.lon}` : 'Tidak tersedia'}</p>
    `;
  }
}

export default DetailPage;
