import '../styles/styles.css';
import App from './pages/app';
import './utils/index';
import { subscribePush } from './utils/push.js';

document.addEventListener('DOMContentLoaded', async () => {
  const app = new App({
    content: document.querySelector('#main-content'),
    drawerButton: document.querySelector('#drawer-button'),
    navigationDrawer: document.querySelector('#navigation-drawer'),
  });
  await app.renderPage();

  window.addEventListener('hashchange', async () => {
    await app.renderPage();
    // Tutup drawer jika pindah halaman (untuk mobile/PWA)
    document.querySelector('#navigation-drawer').classList.remove('open');
  });

  // Tutup drawer jika klik link di nav-list (untuk SPA di GitHub Pages)
  document.querySelectorAll('#nav-list a').forEach(link => {
    link.addEventListener('click', () => {
      document.querySelector('#navigation-drawer').classList.remove('open');
    });
  });
});

// Contoh: panggil subscribePush setelah login/register sukses
document.getElementById('loginNav').addEventListener('click', () => {
  // ...existing login logic...
  subscribePush();
});
