import routes from '../routes/routes';
import { getActiveRoute } from '../routes/url-parser';

class App {
  #content = null;
  #drawerButton = null;
  #navigationDrawer = null;

  constructor({ navigationDrawer, drawerButton, content }) {
    this.#content = content;
    this.#drawerButton = drawerButton;
    this.#navigationDrawer = navigationDrawer;

    this._setupDrawer();
  }

  _setupDrawer() {
    this.#drawerButton.addEventListener('click', () => {
      this.#navigationDrawer.classList.toggle('open');
    });

    // Tutup drawer jika klik link di nav-list (untuk SPA di GitHub Pages)
    this.#navigationDrawer.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => {
        this.#navigationDrawer.classList.remove('open');
      });
    });

    document.body.addEventListener('click', (event) => {
      if (!this.#navigationDrawer.contains(event.target) && !this.#drawerButton.contains(event.target)) {
        this.#navigationDrawer.classList.remove('open');
      }
    });
  }

  async renderPage() {
    const url = getActiveRoute();
    const page = routes[url] || routes['404'];

    // Ambil id dari hash jika ada (untuk detail)
    let id = null;
    if (window.location.hash.startsWith('#/detail/')) {
      id = window.location.hash.split('/')[2] || null;
    }

    // View Transition API
    if (document.startViewTransition) {
      await document.startViewTransition(async () => {
        this.#content.innerHTML = await page.render(id);
        await page.afterRender(id);
      });
    } else {
      this.#content.innerHTML = await page.render(id);
      await page.afterRender(id);
    }
  }
}

async function router() {
  const parsedUrl = UrlParser.parseActiveUrlWithCombiner();
  let page = routes[parsedUrl.resource ? `/${parsedUrl.resource}` : '/'] || routes['404'];
  if (parsedUrl.resource && parsedUrl.id && routes[`/${parsedUrl.resource}/:id`]) {
    page = routes[`/${parsedUrl.resource}/:id`];
  }
  document.getElementById('main-content').innerHTML = await page.render();
  await page.afterRender();
}

export default App;
